import { permit } from './limit.mjs';

test('allows integer counts from 0 through 3 inclusive', () => {
  assert.equal(permit(0), true);
  assert.equal(permit(3), true);
});

test('rejects counts outside the upper and lower bounds', () => {
  assert.equal(permit(-1), false);
  assert.equal(permit(4), false);
});

test('rejects malformed count inputs without coercion', () => {
  for (const malformed of ['2', null, undefined, NaN, Infinity, -Infinity, 1.5]) {
    assert.equal(permit(malformed), false, `${String(malformed)} should be rejected`);
  }
});

